import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');

// Library: none — native interpolate/spring with SVG paths for complex shapes.

const { fontFamily: bebasFamily } = loadBebas();



export type PopUpNotificationProps = Record<string, any>;

const PopUpNotification: React.FC<PopUpNotificationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5, // Unused directly in render but required by schema rules
  mainText = "QUESTION",
  subText = "#1",
  primaryColor = "#27D3C2", // MacroFit Teal
  secondaryColor = "#0B4F53", // Dark Teal
  textColor = "#FFFFFF",
  tiltAngle = -5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Base logical dimensions for the graphic container
  const baseWidth = 900;
  const baseHeight = 500;

  // Scale to occupy ~85% of the screen width (ideal for vertical 9:16)
  const scale = (width * 0.85) / baseWidth;

  // --- Animations ---
  
  // 1. Entrance Pop
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.8 },
  });

  const scaleAnim = interpolate(entranceProgress, [0, 1], [0.3, 1]);
  const opacityAnim = interpolate(entranceProgress, [0, 0.5], [0, 1]);
  const slideYAnim = interpolate(entranceProgress, [0, 1], [100, 0]);

  // 2. Continuous floating effect (starts after entrance)
  const floatY = Math.sin(frame / 20) * 8;
  const floatRot = Math.sin(frame / 25) * 1.5;

  // 3. Text entrance stagger
  const textSpring = spring({
    frame: frame - 6, // Delay text slightly
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  const textOpacity = interpolate(textSpring, [0, 0.8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textSlideX = interpolate(textSpring, [0, 1], [-40, 0]);

  const subTextSpring = spring({
    frame: frame - 10,
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  const subTextOpacity = interpolate(subTextSpring, [0, 0.8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const subTextSlideX = interpolate(subTextSpring, [0, 1], [40, 0]);

  // 4. Glow pulse
  const glowOpacity = interpolate(
    Math.sin(frame / 15),
    [-1, 1],
    [0.6, 1]
  );

  // --- Path Definitions ---
  // A complex sci-fi/tech chamfered panel path
  const panelPath = `
    M 50, 100 
    L 100, 50 
    L 350, 50 
    L 380, 70 
    L 800, 70 
    L 850, 120 
    L 850, 400 
    L 800, 450 
    L 550, 450 
    L 520, 430 
    L 100, 430 
    L 50, 380 
    Z
  `;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: bebasFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        // Ensure no CSS transitions interfere with frame purity
        transition: "none", 
      }}
    >
      <div
        style={{
          width: baseWidth,
          height: baseHeight,
          position: "relative",
          opacity: opacityAnim,
          transform: `scale(${scale * scaleAnim}) translateY(${
            slideYAnim + floatY
          }px) rotate(${tiltAngle + floatRot}deg)`,
          filter: "drop-shadow(15px 25px 30px rgba(0,0,0,0.5))",
          transition: "none",
        }}
      >
        {/* SVG Background Layer */}
        <svg
          viewBox={`0 0 ${baseWidth} ${baseHeight}`}
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            overflow: "visible",
            transition: "none",
          }}
        >
          <defs>
            <filter id="neon-glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="15" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Outer Glowing Stroke */}
          <path
            d={panelPath}
            fill="none"
            stroke={primaryColor}
            strokeWidth="20"
            filter="url(#neon-glow)"
            opacity={glowOpacity}
            style={{ transition: "none" }}
          />

          {/* Main Dark Body */}
          <path
            d={panelPath}
            fill={secondaryColor}
            fillOpacity={0.5}
            stroke={primaryColor}
            strokeWidth="8"
            style={{ transition: "none" }}
          />

          {/* Tech Accents (Dashed Lines) - Top Left */}
          <g
            transform="translate(130, 85) skewX(-25)"
            fill={primaryColor}
            style={{ transition: "none" }}
          >
            <rect x="0" y="0" width="18" height="12" />
            <rect x="25" y="0" width="18" height="12" />
            <rect x="50" y="0" width="18" height="12" />
            <rect x="75" y="0" width="18" height="12" />
          </g>

          {/* Tech Accents (Dashed Lines) - Bottom Right */}
          <g
            transform="translate(680, 415) skewX(-25)"
            fill={primaryColor}
            style={{ transition: "none" }}
          >
            <rect x="0" y="0" width="18" height="12" />
            <rect x="25" y="0" width="18" height="12" />
            <rect x="50" y="0" width="18" height="12" />
            <rect x="75" y="0" width="18" height="12" />
          </g>
        </svg>

        {/* Text Layer */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            padding: "0 80px",
            // Inner skew applied to text to match the image's slanted font feel
            transform: "skewX(-8deg)",
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: 190,
              color: textColor,
              lineHeight: 0.8,
              letterSpacing: "4px",
              textShadow: "6px 8px 0px rgba(0,0,0,0.4), 0px 15px 20px rgba(0,0,0,0.6)",
              opacity: textOpacity,
              transform: `translateX(${textSlideX}px)`,
              width: "100%",
              textAlign: "left",
              paddingTop: "20px",
              transition: "none",
            }}
          >
            {mainText}
          </div>
          <div
            style={{
              fontSize: 160,
              color: primaryColor,
              lineHeight: 0.8,
              letterSpacing: "2px",
              textShadow: "5px 6px 0px rgba(0,0,0,0.4), 0px 10px 15px rgba(0,0,0,0.6)",
              opacity: subTextOpacity,
              transform: `translateX(${subTextSlideX}px)`,
              alignSelf: "flex-end",
              marginTop: "5px",
              marginRight: "40px",
              transition: "none",
            }}
          >
            {subText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PopUpNotification;